{"command": "cd /workspace/work && cat > compose.py <<'EOF'
import base64, json, sys
import numpy as np
import synth

# ---------- constants ----------
CH = dict(KICK=0, SNARE=1, HAT=2, FX=3, BASS=4, STAB=5, ARP=6, LEAD=7, HARM=8, PAD=9)
IN = dict(KICK=1, SNARE=2, CHH=3, OHH=4, BASS=5, STMIN=6, STMAJ=7, ARP=8,
          LEAD=9, HARM=10, PDMIN=11, PDMAJ=12, RISER=13, IMPACT=14)
ARP_FX=0; PORTA=3; VIB=4; EXT=14
NAMES=['C','C#','D','D#','E','F','F#','G','G#','A','A#','B']
def nm(midi): return f"{NAMES[midi%12]}-{midi//12-1}"
def midi(semi, octv): return 12*(octv+1)+semi

CHORD = {'Am':(9,'min'),'F':(5,'maj'),'G':(7,'maj'),'E':(4,'maj'),'C':(0,'maj'),'Dm':(2,'min')}
PROG = {0:['Am','Am','F','G'], 1:['Am','Am','F','G'], 2:['Am','G','F','E'],
        3:['F','C','Dm','E'], 4:['Am','Am','Am','Am'], 5:['F','G','Am','Am']}
BASS_OCT = {9:1, 5:1, 7:1, 4:1, 0:2, 2:2}

def vcol(v): return 16+max(0,min(64,int(v)))

class Ev:
    def __init__(self):
        self.ops=[]; self.cells={}
    def set(self, pat, row, ch, note=None, ins=None, vol=None, fx=None, param=None):
        key=(pat,row,ch)
        cell=dict()
        if key in self.cells and note is not None:
            print(f'!! overwrite note at pat{pat} row{row} ch{ch}: {self.cells[key]} -> {note}')
        c = self.cells.get(key, {})
        c.update({k:v for k,v in dict(note=note,ins=ins,vol=vol,fx=fx,param=param).items() if v is not None})
        self.cells[key]=c
    def emit(self):
        for (pat,row,ch),c in sorted(self.cells.items()):
            a={'pattern':pat,'row':row,'channel':ch}
            if 'note' in c: a['note']=c['note']
            if 'ins' in c: a['instrument']=c['ins']
            if 'vol' in c: a['volume']=vcol(c['vol'])
            if 'fx' in c: a['effect']=c['fx']; a['effect_param']=c['param']
            self.ops.append({'name':'pattern_set_cell','arguments':a})
        return self.ops

E = Ev()

MIN_T=[12,15,19,24]; MAJ_T=[12,16,19,24]
MIN_LO=[0,3,7,12];  MAJ_LO=[0,4,7,12]

def chord_midi(root_semi, octv): return midi(root_semi, octv)

# ---------------- drums ----------------
def kick(pat, row, v=58, ch=CH['KICK']):
    E.set(pat,row,ch, note='C-4', ins=IN['KICK'], vol=v)
def snare(pat,row,v=64):
    E.set(pat,row,CH['SNARE'], note='D-4', ins=IN['SNARE'], vol=v)
def chh(pat,row,v=40):
    E.set(pat,row,CH['HAT'], note='C-4', ins=IN['CHH'], vol=v)
def ohh(pat,row,v=34):
    E.set(pat,row,CH['FX'], note='C-4', ins=IN['OHH'], vol=v)

# ---------------- tonal helpers ----------------
def bass_note(pat,row,root,hi=False,v=56):
    semi,q=CHORD[root]; o=BASS_OCT[semi]
    note=nm(midi(semi, o+(1 if hi else 0)))
    E.set(pat,row,CH['BASS'], note=note, ins=IN['BASS'], vol=v)
def stab(pat,row,root,v=44,octv=3):
    semi,q=CHORD[root]
    ins=IN['STMIN'] if q=='min' else IN['STMAJ']
    E.set(pat,row,CH['STAB'], note=nm(midi(semi,octv)), ins=ins, vol=v)
def arp(pat,row,root,v=38,hi=False,lo=False):
    semi,q=CHORD[root]
    tones = (MIN_LO if q=='min' else MAJ_LO) if lo else (MIN_T if q=='min' else MAJ_T)
    idx = (row % 4) if not lo else ((row % 8)//2)
    base = chord_midi(semi,3) + (12 if hi else 0)
    E.set(pat,row,CH['ARP'], note=nm(base+tones[idx]), ins=IN['ARP'], vol=v)
def pad(pat,row,root,v=32,octv=3):
    semi,q=CHORD[root]
    ins=IN['PDMIN'] if q=='min' else IN['PDMAJ']
    E.set(pat,row,CH['PAD'], note=nm(midi(semi,octv)), ins=ins, vol=v)
def bass_bar(pat,bar,root,main=True,pickup=False):
    rows=[0,2,4,6,8,10,12,14] if main else [0,8]
    for r in rows:
        hi = (r%4==2)
        bass_note(pat,bar*16+r,root,hi=hi,v=60 if not hi else 44)
    if pickup:
        bass_note(pat,bar*16+13,root,hi=True,v=46)
        semi,q=CHORD[root]; o=BASS_OCT[semi]
        E.set(pat,bar*16+15,CH['BASS'], note=nm(midi(semi,o+1)+7), ins=IN['BASS'], vol=48)

# ================= pattern content =================
# --- P0 intro (Am Am F G) ---
pr=PROG[0]
pad(0,0,'Am',30); pad(0,32,'F',30); pad(0,48,'G',30)
vol_cyc=[38,26,30,26]
for r in range(64):
    arp(0,r,pr[r//16],v=vol_cyc[r%4])
for b in range(4):
    bass_note(0,b*16,pr[b],v=56)
for r in (32,36,40,44): kick(0,r,52)
for r in (48,52,56,60): kick(0,r,58)
for r in range(32,64,2): chh(0,r, 22 if r<48 else (26 if r%4==0 else 30))
for r,v in ((34,30),(38,26),(42,30),(46,26),(50,30),(54,26),(58,30),(62,26)):
    stab(0,r,pr[r//16],v=v)
snare(0,52,40); snare(0,60,48); snare(0,62,52); snare(0,63,56)
E.set(0,32,CH['FX'], note='C-4', ins=IN['RISER'], vol=34)
E.set(0,0,CH['HARM'], vol=0)   # ensure silence if looped

# --- main groove generator (used by P1,P2,P5) ---
def main_groove(p, fills=(), extra_o2=False):
    pr=PROG[p]
    for b in range(4):
        for r in (0,4,8,12): kick(p,b*16+r, 62 if r==0 else 58)
        for r in range(0,16,2): chh(p,b*16+r, 34 if r%4==0 else 46)
        for r in (2,6,10,14): stab(p,b*16+r,pr[b], v=[46,34,46,34][r//4], octv=(4 if p==5 else 3))
        bass_bar(p,b,pr[b], main=True, pickup=(b==3))
        for r in range(16):
            arp(p,b*16+r,pr[b], v=[38,26,30,26][r%4], hi=(p==5 or (b==3 and r>=0)))
    # snares per bar
    for b in range(4):
        snare(p,b*16+4,64); snare(p,b*16+12,60)
    if 1 in fills: snare(p,1*16+3,20); snare(p,1*16+14,44); snare(p,1*16+15,50)
    if 3 in fills:
        snare(p,3*16+3,20); snare(p,3*16+13,44); snare(p,3*16+14,50); snare(p,3*16+15,54)
    # extra 16th hats on bar 2
    chh(p,2*16+7,30); chh(p,2*16+15,30)

def pads_for(p):
    pr=PROG[p]; last=None
    for b in range(4):
        if pr[b]!=last:
            pad(p,b*16,
                pr[b], v=32); last=pr[b]

# --- P1 ---
main_groove(1, fills=(1,3))
pads_for(1)
E.set(1,0,CH['FX'], note='C-4', ins=IN['IMPACT'], vol=34)
for r in (14,30,46,54): ohh(1,r,34)
E.set(1,0,CH['HARM'], vol=0)
LEAD_P1=[(0,0,'E-5',None,60),(0,4,'G-5',None,58),(0,8,'A-5',(VIB,0x45),60),(0,12,None,(VIB,0x45),None),
 (1,0,'A-5',None,60),(1,2,'G-5',None,56),(1,4,'E-5',None,56),(1,8,'D-5',None,56),(1,10,'E-5',None,56),(1,12,'C-5',None,56),(1,14,'D-5',None,58),
 (2,0,'F-5',None,60),(2,4,'E-5',None,58),(2,8,'C-5',None,58),(2,10,'D-5',None,54),(2,12,'E-5',None,54),(2,14,'F-5',None,58),
 (3,0,'G-5',None,60),(3,2,None,(VIB,0x45),None),(3,6,None,(VIB,0x45),None),(3,8,'B-5',None,60),(3,12,'A-5',None,58),(3,14,'B-5',None,58)]
for b,r,n,f,v in LEAD_P1:
    E.set(1,b*16+r,CH['LEAD'], note=n, ins=(IN['LEAD'] if n else None), vol=v, fx=(f[0] if f else None), param=(f[1] if f else None))

# --- P2 ---
main_groove(2, fills=(3,))
pads_for(2)
for r in (14,30,46,54): ohh(2,r,34)
LEAD_P2=[(0,0,'C-6',(PORTA,0x40),62),(0,4,None,(VIB,0x47),None),(0,8,None,(VIB,0x47),None),
 (0,10,'B-5',None,56),(0,12,'A-5',None,56),(0,14,'G-5',None,56),
 (1,0,'B-5',None,60),(1,4,'G-5',None,58),(1,8,'A-5',None,58),(1,12,'B-5',None,60),(1,14,'C-6',None,60),
 (2,0,'C-6',None,62),(2,2,None,(ARP_FX,0x47),None),(2,4,None,(ARP_FX,0x47),None),
 (2,8,'C-6',None,60),(2,10,'D-6',None,60),(2,12,'C-6',None,58),(2,14,'A-5',None,58),
 (3,0,'G#-5',None,60),(3,4,'B-5',None,60),(3,8,'E-5',(VIB,0x47),60),(3,12,None,(VIB,0x47),None),
 (3,14,'D-5',None,56),(3,15,'E-5',None,56)]
for b,r,n,f,v in LEAD_P2:
    E.set(2,b*16+r,CH['LEAD'], note=n, ins=(IN['LEAD'] if n else None), vol=v, fx=(f[0] if f else None), param=(f[1] if f else None))
HARM_P2=[(2,0,'A-5',42),(2,8,'A-5',40),(2,10,'B-5',40),(2,12,'A-5',40),(2,14,'F-5',40),
 (3,0,'E-5',40),(3,4,'G#-5',40),(3,8,'C-5',40),(3,12,None,None)]
for b,r,n,v in HARM_P2:
    E.set(2,b*16+r,CH['HARM'], note=n, ins=(IN['HARM'] if n else None), vol=v,
          fx=(VIB if n=='C-5' else None), param=(0x45 if n=='C-5' else None))

# --- P3 breakdown (F C Dm E) ---
pr=PROG[3]
E.set(3,0,CH['LEAD'], vol=0); E.set(3,0,CH['HARM'], vol=0)
E.set(3,0,CH['FX'], note='C-4', ins=IN['IMPACT'], vol=26)
pads_for_v=[34,32,34,34]
last=None
for b in range(4):
    if pr[b]!=last: pad(3,b*16,pr[b],v=34); last=pr[b]
    kick(3,b*16+0,58); kick(3,b*16+8,54)
    snare(3,b*16+4,42); snare(3,b*16+12,42)
    for r in range(0,16,2): chh(3,b*16+r, 22 if r%4==0 else 30)
    stab(3,b*16+2,pr[b],30); stab(3,b*16+10,pr[b],26)
    bass_note(3,b*16+0,pr[b],56); bass_note(3,b*16+8,pr[b],50)
    if b in (1,3):
        semi,ql=CHORD[pr[b]]; o=BASS_OCT[semi]
        E.set(3,b*16+14,CH['BASS'], note=nm(midi(semi,o+1)+7), ins=IN['BASS'], vol=42)
    for r in range(0,16,2):
        arp(3,b*16+r,pr[b], v=30, lo=True)
snare(3,3*16+13,30); snare(3,3*16+14,36); snare(3,3*16+15,42)

# --- P4 build (Am x4) ---
pr=PROG[4]
pad(4,0,'Am',32)
E.set(4,0,CH['FX'], note='C-4', ins=IN['IMPACT'], vol=30)
E.set(4,32,CH['FX'], note='C-4', ins=IN['RISER'], vol=40)
for b in range(4):
    for r in (0,4,8,12): kick(4,b*16+r, 62 if r==0 else 58)
    for r in range(0,16,2): chh(4,b*16+r, (34 if r%4==0 else 44) if b<3 else 38)
for b,v in ((0,34),(1,40),(2,46),(3,52)):
    for i,r in enumerate((2,6,10,14)): stab(4,b*16+r,'Am', v=v+(4 if i%2==0 else 0))
bass_bar(4,0,'Am',main=True); bass_bar(4,1,'Am',main=True)
for b in (2,3):
    for r in range(16):
        bass_note(4,b*16+r,'Am', hi=(r%2==1), v=(56 if r%2==0 else 38))
snare(4,4,60); snare(4,12,56); snare(4,20,60); snare(4,28,56)
for r in range(32,48,2): snare(4,r, 40+(r-32))
for r in range(48,64): snare(4,r, 44+(r-48)*1.25)
for b,base in ((0,40),(1,44),(2,48),(3,52)):
    for r in range(16):
        arp(4,b*16+r,'Am', v=min(64,base+[0,-8,-4,-8][r%4]), hi=(b==3))
LEAD_P4=[(0,0,'E-5'),(0,4,'G-5'),(0,8,'A-5'),
 (1,0,'C-6'),(1,4,'B-5'),(1,8,'A-5'),(1,12,'G-5'),
 (2,0,'E-5'),(2,4,'G-5'),(2,8,'A-5'),(2,12,'C-6')]
for b,r,n in LEAD_P4:
    cut = 0xC0|3
    E.set(4,b*16+r,CH['LEAD'], note=n, ins=IN['LEAD'], vol=56, fx=EXT, param=cut)
for r,n,vv in ((48,'E-5',52),(50,'G-5',54),(52,'A-5',56),(54,'B-5',58),(56,'C-6',60),(58,'D-6',62)):
    E.set(4,r,CH['LEAD'], note=n, ins=IN['LEAD'], vol=vv, fx=EXT, param=0xC3)
E.set(4,60,CH['LEAD'], note='E-6', ins=IN['LEAD'], vol=64, fx=VIB, param=0x55)
E.set(4,62,CH['LEAD'], fx=VIB, param=0x55)
ohh(4,10,32); ohh(4,26,32)

# --- P5 final (F G Am Am) ---
main_groove(5, fills=(1,3))
pads_for(5)
E.set(5,0,CH['FX'], note='C-4', ins=IN['IMPACT'], vol=40)
for b in range(4):
    ohh(5,b*16+6,36); ohh(5,b*16+14,36)
LEAD_P5=[(0,0,'A-5',None,62),(0,4,'C-6',None,60),(0,8,'F-6',(VIB,0x46),62),(0,12,None,(VIB,0x46),None),(0,14,'E-6',None,60),
 (1,0,'D-6',(VIB,0x44),62),(1,4,'B-5',None,58),(1,8,'G-5',None,58),(1,12,'B-5',None,60),(1,14,'D-6',None,62),
 (2,0,'E-6',None,62),(2,4,'C-6',None,60),(2,8,'A-5',None,58),(2,12,'G-5',None,56),(2,14,'A-5',None,58),
 (3,0,'A-5',None,62),(3,2,None,(VIB,0x47),None),(3,6,None,(VIB,0x47),None),(3,12,None,(ARP_FX,0x37),None)]
for b,r,n,f,v in LEAD_P5:
    E.set(5,b*16+r,CH['LEAD'], note=n, ins=(IN['LEAD'] if n else None), vol=v, fx=(f[0] if f else None), param=(f[1] if f else None))
HARM_P5=[(0,0,'F-5',(None,None)),(0,4,'A-5',(None,None)),(0,8,'D-6',(VIB,0x45)),(0,14,'C-6',(None,None)),
 (1,0,'B-5',(None,None)),(1,4,'G-5',(None,None)),(1,8,'E-5',(None,None)),(1,12,'G-5',(None,None)),(1,14,'B-5',(None,None)),
 (2,0,'C-6',(None,None)),(2,4,'A-5',(None,None)),(2,8,'F-5',(None,None)),(2,12,'E-5',(None,None)),(2,14,'F-5',(None,None)),
 (3,0,'F-5',(VIB,0x45))]
for b,r,n,f in HARM_P5:
    E.set(5,b*16+r,CH['HARM'], note=n, ins=IN['HARM'], vol=42, fx=(f[0] if f[0] else None), param=(f[1] if f and f[1] else None))

# ================= assemble ops =================
ops=[]
ops.append({'name':'module_new','arguments':{'channels':10,'name':'dawn patrol'}})

samples = {
 IN['KICK']:  (synth.make_kick(),      'KNG-kick'),
 IN['SNARE']: (synth.make_snare(),     'KNG-snare'),
