 IN['OHH']:   (synth.make_hat(9,0.5,6000),  'KNG-hatO'),
 IN['BASS']:  (synth.make_bass(),      'KNG-bass'),
 IN['STMIN']: (synth.make_stab(True),  'KNG-stabm'),
 IN['STMAJ']: (synth.make_stab(False), 'KNG-stabM'),
 IN['ARP']:   (synth.make_arp(),       'KNG-blip'),
 IN['LEAD']:  (synth.make_lead(),      'KNG-lead'),
 IN['HARM']:  (synth.make_lead(),      'KNG-lead2'),
 IN['PDMIN']: (synth.make_pad(True),   'KNG-padm'),
 IN['PDMAJ']: (synth.make_pad(False),  'KNG-padM'),
 IN['RISER']: (synth.make_riser(),     'KNG-rise'),
 IN['IMPACT']:(synth.make_impact(),    'KNG-boom'),
}
