PAN = {1:128,2:128,3:156,4:108,5:128,6:120,7:120,8:148,9:128,10:120,11:140,12:140,13:128,14:128}
FINETUNE = {10:8}

names = {1:'kick',2:'snare',3:'hatC',4:'hatO',5:'bass',6:'stabMin',7:'stabMaj',
         8:'arpBlip',9:'theLead',10:'harmLead',11:'padMinor',12:'padMajor',13:'riser',14:'impact'}

for ins,(res,nm_) in samples.items():
    pcm, grid, rel = res[0], res[1], res[2]
    ops.append({'name':'sample_create_from_pcm','arguments':{
        'instrument':ins,'sample':0,'pcm':base64.b64encode(pcm).decode(),'encoding':'int16','name':nm_}})
    meta={'instrument':ins,'sample':0,'volume':VOL[ins],'panning':PAN[ins],
          'relative_note':rel,'finetune':FINETUNE.get(ins,0)}
    if len(res)==5:
        meta['loop_start']=res[3]; meta['loop_length']=res[4]; meta['flags']=1
    ops.append({'name':'sample_set','arguments':meta})
    ops.append({'name':'instrument_set','arguments':{'instrument':ins,'name':names[ins]}})

for p in range(6):
    ops.append({'name':'pattern_set_length','arguments':{'pattern':p,'rows':64}})

